DROP TABLE IF EXISTS `omr_scoring_job_result`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `omr_scoring_job_result` (
  `job_result_uuid` binary(16) NOT NULL,
  `attempt_uuid` binary(16) DEFAULT NULL,
  `error_message` text,
  `extracted_payload_json` text,
  `job_uuid` binary(16) NOT NULL,
  `page_number` int DEFAULT NULL,
  `paper_code` varchar(50) DEFAULT NULL,
  `raw_image_url` varchar(1000) DEFAULT NULL,
  `school_year` varchar(20) DEFAULT NULL,
  `score` decimal(10,2) DEFAULT NULL,
  `scored_image_url` varchar(1000) DEFAULT NULL,
  `status` enum('COMPLETED','EXTRACTED','FAILED','IMPORTING') NOT NULL,
  `student_code` varchar(20) DEFAULT NULL,
  `student_uuid` binary(16) DEFAULT NULL,
  `student_fullname` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`job_result_uuid`),
  KEY `idx_omr_scoring_job_result_job` (`job_uuid`),
  KEY `idx_omr_scoring_job_result_attempt` (`attempt_uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
