CREATE TABLE `question` (
  `question_uuid` binary(16) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `created_by_user_uuid` binary(16) NOT NULL,
  `grade_id` bigint NOT NULL,
  `is_active` bit(1) NOT NULL,
  `question_content` text NOT NULL,
  `question_topic` varchar(255) DEFAULT NULL,
  `question_type` enum('MCQ','SAQ','TFQ') NOT NULL,
  `image_path` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`question_uuid`),
  KEY `idx_question_grade_type_topic` (`grade_id`,`question_type`,`question_topic`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
